class UnitLevelStaticDataTester {
public:
    static UnitLevelStaticDataKey make_key (u16 raw) {
        return UnitLevelStaticDataKey::from_raw(raw);
    }
};

void test_set_items_updates_count () {
    static UnitLevelStaticDataStruct items[3];
    items[0].up_prob = 1;  items[0].mvt_boost = 10;
    items[1].up_prob = 2;  items[1].mvt_boost = 20;
    items[2].up_prob = 3;  items[2].mvt_boost = 30;
    UnitLevelStaticData data;
    data.set_items(items, 3);
    note_result(data.get_item_count() == 3, "set_items updates item count");
    summarize_test_results();
}

void test_get_item_returns_expected_struct_by_key () {
    static UnitLevelStaticDataStruct items[4];
    items[0].up_prob = 7;   items[0].mvt_boost = 70;
    items[1].up_prob = 8;   items[1].mvt_boost = 80;
    items[2].up_prob = 9;   items[2].mvt_boost = 90;
    items[3].up_prob = 10;  items[3].mvt_boost = 100;
    UnitLevelStaticData data;
    data.set_items(items, 4);

    UnitLevelStaticDataKey key = UnitLevelStaticDataTester::make_key(2);
    const UnitLevelStaticDataStruct& item = data.get_item(key);

    note_result(item.up_prob == 9, "get_item returns expected member1");
    note_result(item.mvt_boost == 90, "get_item returns expected member2");
    summarize_test_results();
}

void test_get_item_returns_reference_to_backing_array () {
    static UnitLevelStaticDataStruct items[2];
    items[0].up_prob = 11;  items[0].mvt_boost = 110;
    items[1].up_prob = 12;  items[1].mvt_boost = 120;
    UnitLevelStaticData data;
    data.set_items(items, 2);

    UnitLevelStaticDataKey key = UnitLevelStaticDataTester::make_key(1);
    const UnitLevelStaticDataStruct& item = data.get_item(key);

    note_result(&item == &items[1], "get_item returns reference into backing array");
    summarize_test_results();
}

void test_set_items_can_replace_array_and_count () {
    static UnitLevelStaticDataStruct items_a[2];
    items_a[0].up_prob = 21; items_a[0].mvt_boost = 210;
    items_a[1].up_prob = 22; items_a[1].mvt_boost = 220;
    static UnitLevelStaticDataStruct items_b[5];
    items_b[0].up_prob = 31; items_b[0].mvt_boost = 131;
    items_b[1].up_prob = 32; items_b[1].mvt_boost = 132;
    items_b[2].up_prob = 33; items_b[2].mvt_boost = 133;
    items_b[3].up_prob = 34; items_b[3].mvt_boost = 134;
    items_b[4].up_prob = 35; items_b[4].mvt_boost = 135;

    UnitLevelStaticData data;
    data.set_items(items_a, 2);
    note_result(data.get_item_count() == 2, "initial array count set");

    data.set_items(items_b, 5);
    note_result(data.get_item_count() == 5, "replacement array count set");
    UnitLevelStaticDataKey key = UnitLevelStaticDataTester::make_key(4);
    const UnitLevelStaticDataStruct& item = data.get_item(key);
    note_result(item.up_prob == 35, "replacement array item accessible");
    summarize_test_results();
}

void test_zero_count_is_allowed () {
    static UnitLevelStaticDataStruct items[1];
    items[0].up_prob = 41; items[0].mvt_boost = 141;
    UnitLevelStaticData data;
    data.set_items(items, 0);
    note_result(data.get_item_count() == 0, "zero item count can be stored");
    summarize_test_results();
}

void test_take_ownership_copies_backing_array () {
    UnitLevelStaticDataStruct* items = new UnitLevelStaticDataStruct[2];
    items[0].up_prob = 51; items[0].mvt_boost = 151;
    items[1].up_prob = 52; items[1].mvt_boost = 152;
    UnitLevelStaticData data;
    data.set_items(items, 2);
    UnitLevelStaticDataKey key = UnitLevelStaticDataTester::make_key(1);
    const void* src_ref = &data.get_item(key);
    data.take_ownership();
    const UnitLevelStaticDataStruct& item = data.get_item(key);

    note_result(&item != src_ref, "take_ownership uses a distinct buffer");
    note_result(item.up_prob == 52, "take_ownership preserves member1");
    note_result(item.mvt_boost == 152, "take_ownership preserves member2");
    data.release_items();
    summarize_test_results();
}

